<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { defaultSyncPolicyValues, type SyncSource, type SyncPolicyValues } from '@apicc/core/sync/shared';
import type { ApiccApi } from '../../../../shared/types.js';
import type { createSynchronizationStore } from '../../stores/synchronization.js';
import SyncSourceForm from './SyncSourceForm.vue';
import SyncDiffView from './SyncDiffView.vue';
import SyncHistory from './SyncHistory.vue';
import { utcTime, shortIdentity, readableReason, policyFields } from './presentation.js';
import '../../styles/sync-presentation.css';
const props = defineProps<{ store: ReturnType<typeof createSynchronizationStore>; modules?: { id: string; name: string }[]; api?: ApiccApi; contractProjectId?: string; readOnly?: boolean }>();
const emit = defineEmits<{ close: [] }>();
let actionEpoch = 0;
const scrollArea = ref<HTMLElement>();
function navigateTo(id: 'sync-sources' | 'sync-diff' | 'sync-history' | 'sync-settings') {
  const area = scrollArea.value, target = area?.querySelector<HTMLElement>(`#${id}`);
  if (!area || !target) return;
  target.focus({ preventScroll: true });
  area.scrollTo({ top: Math.max(0, target.getBoundingClientRect().top - area.getBoundingClientRect().top + area.scrollTop - 10), behavior: 'smooth' });
}
const { t, te, locale } = useI18n(); const search = ref(''), searchInput = ref<HTMLInputElement>(), editing = ref('');
const policyDraft = reactive<SyncPolicyValues>({ ...defaultSyncPolicyValues }), redirects = ref(5);
const rule = reactive<SyncSource['schedule']['rule']>({ kind: 'cron', expression: '0 0 * * * *', timeZone: 'UTC', dstOverlap: 'first' });
watch(() => props.store.settings, value => { if (value) { Object.assign(policyDraft, value.policy); redirects.value = value.maxRedirects; } }, { immediate: true });
watch(() => props.store.schedule, value => { if (value) Object.assign(rule, value.rule); }, { immediate: true });
watch(locale, value => { props.store.locale = value === 'en' ? 'en' : 'zh-CN'; }, { immediate: true });
watch(() => props.store.scope, () => { actionEpoch++; editing.value = ''; search.value = ''; if (props.store.visible) void props.store.load(); });
watch(() => props.store.sourceId, () => { actionEpoch++; editing.value = ''; });
watch(editing, () => { actionEpoch++; });
onMounted(() => { props.store.setVisible(true); if (props.store.scope) void props.store.load(); });
onBeforeUnmount(() => props.store.setVisible(false));
const sources = computed(() => props.store.sources.filter(s => !search.value || [s.id, s.kind, s.kind === 'url' ? s.url : s.repositoryUrl].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const can = (capability: string) => props.store.scope?.kind === 'local' ? !props.readOnly : !!props.store.capabilities?.includes(capability);
const reason = (code: string) => readableReason(code, t, te);
function clear() { search.value = ''; searchInput.value?.focus(); }
async function action(operation: () => Promise<unknown>): Promise<boolean> { const owner = actionEpoch; try { await operation(); return owner === actionEpoch; } catch (cause) { if (owner === actionEpoch) props.store.error = cause && typeof cause === 'object' && 'code' in cause && typeof cause.code === 'string' ? cause.code : cause instanceof Error ? cause.message : 'SYNC_REQUEST_FAILED'; return false; } }
async function saveSource(source: SyncSource, revision: string) { if (await action(() => props.store.saveSource(source, revision))) editing.value = ''; }
const fieldValue = (value: number | undefined, unit: string) => value === undefined ? t('sync.inherited') : `${value.toLocaleString(locale.value)} ${t('sync.' + unit)}${unit === 'bytes' ? ` (${Number((value / 1048576).toFixed(3))} MiB)` : ''}`;
</script>
<template>
  <section class="sync-panel" data-testid="sync-panel" role="region" :aria-label="t('sync.title')">
    <header class="sync-fixed"><div class="sync-heading"><h2>{{ t('sync.title') }}</h2><button @click="emit('close')">{{ t('sync.close') }}</button></div>
      <div class="sync-context"><p><strong>{{ t('sync.location') }}: {{ t(store.scope?.kind === 'online' ? 'sync.online' : 'sync.local') }}</strong></p><p>{{ t(store.scope?.kind === 'online' ? 'sync.onlineNote' : 'sync.localNote') }}</p><p v-if="store.scope?.kind === 'local'">{{ t('sync.approvalScope') }}</p></div>
      <div class="sync-toolbar"><input ref="searchInput" v-model="search" data-testid="sync-search" :aria-label="t('sync.search')" :placeholder="t('sync.search')" /><button data-testid="sync-clear" @click="clear">{{ t('sync.clear') }}</button><button data-testid="sync-refresh" :disabled="store.busy" @click="store.refresh()">{{ t('sync.refresh') }}</button></div>
      <nav :aria-label="t('sync.sectionNavigation')"><a href="#sync-sources" @click.prevent="navigateTo('sync-sources')">{{ t('sync.sources') }}</a><a href="#sync-diff" @click.prevent="navigateTo('sync-diff')">{{ t('sync.diff') }}</a><a href="#sync-history" @click.prevent="navigateTo('sync-history')">{{ t('sync.history') }}</a><a href="#sync-settings" @click.prevent="navigateTo('sync-settings')">{{ t('sync.settings') }}</a></nav>
      <p v-if="store.error" role="alert">{{ reason(store.error) }}</p><p v-if="store.persistenceError" role="alert">{{ reason(store.persistenceError) }}</p>
    </header>
    <div ref="scrollArea" class="sync-scroll" style="overflow-y:auto">
      <section id="sync-sources" tabindex="-1"><h3>{{ t('sync.sources') }}</h3><button :disabled="!can('sync.manage')" @click="editing = 'new'">{{ t('sync.newSource') }}</button><p v-if="!store.sources.length" class="sync-empty">{{ t('sync.noSources') }}</p><p v-else-if="!sources.length" data-testid="sync-source-empty" class="sync-empty" role="status">{{ t('sync.noMatchingSources') }}</p><ul class="sync-source-list"><li v-for="source in sources" :key="source.id"><button :aria-pressed="store.sourceId === source.id" @click="store.selectSource(source.id)">{{ source.kind === 'url' ? source.url : source.repositoryUrl }} <span>{{ source.kind === 'url' ? 'URL' : source.kind === 'git-https' ? 'Git HTTPS' : 'Git SSH' }} · {{ t('sync.sourceRevision') }} {{ source.revision }}</span></button></li></ul>
        <template v-if="store.selectedSource"><p>{{ t('sync.sourceId') }}: {{ store.selectedSource.id }}</p><button data-testid="sync-edit-source" :disabled="!can('sync.manage')" @click="editing = 'edit'">{{ t('sync.editSource') }}</button><button data-testid="sync-check" :disabled="store.busy || !can('sync.check') || store.policy?.status === 'invalid'" @click="store.check()">{{ t('sync.check') }}</button><button v-if="store.localCheckId || store.checkStatus && ['queued','running','waiting','cancelling'].includes(store.checkStatus.state)" @click="action(() => store.cancel())">{{ t('sync.cancel') }}</button><p v-if="!can('sync.check')">{{ t('sync.noAccess') }}</p></template>
        <SyncSourceForm v-if="editing && store.scope" :key="editing + store.sourceId" :source="editing === 'new' ? null : store.selectedSource" :modules="modules ?? []" :scope="store.scope" :materials="store.materials" :api="api" :contract-project-id="contractProjectId" :disabled="!can('sync.manage')" :can-manage-materials="can('credential.manage')" @save="saveSource" @material-saved="store.load()" />
        <section v-if="store.checkStatus"><h4>{{ t('sync.checkState') }}: {{ t('sync.' + store.checkStatus.state) }}</h4><p v-if="store.checkStatus.reasonCode">{{ reason(store.checkStatus.reasonCode) }}</p><p v-if="store.checkStatus.detailCode">{{ reason(store.checkStatus.detailCode) }}</p><dl><dt>{{ t('sync.created') }}</dt><dd><time :title="String(store.checkStatus.createdAtMs)">{{ utcTime(store.checkStatus.createdAtMs) }}</time></dd><dt>{{ t('sync.completed') }}</dt><dd><time :title="String(store.checkStatus.completedAtMs)">{{ utcTime(store.checkStatus.completedAtMs) ?? t('sync.pending') }}</time></dd></dl><button @click="store.readCheck()">{{ t('sync.refresh') }}</button></section>
        <dl v-if="store.lookup"><dt>{{ t('sync.latestAttempt') }}</dt><dd>{{ utcTime(store.lookup.latestAttempt?.createdAtMs) ?? t('sync.notCollected') }}</dd><dt>{{ t('sync.latestSuccess') }}</dt><dd>{{ utcTime(store.lookup.latestSuccess?.completedAtMs) ?? t('sync.notCollected') }}</dd></dl>
      </section>
      <section id="sync-diff" tabindex="-1"><h3>{{ t('sync.diff') }}</h3><p v-if="store.candidateSuperseded" data-testid="sync-apply-reason" role="status">{{ reason('SYNC_CANDIDATE_SUPERSEDED') }}</p><SyncDiffView v-if="store.candidate" :view="store.candidate" :decisions="store.decisions" :search="search" :details="store.fixedDetails" :detail-change-id="store.detailChangeId" :detail-busy="store.detailBusy" :detail-errors="store.detailErrors" @decide="store.decide" @detail="store.loadDetail" @reader="store.selectDetailChange" /><p v-else>{{ t('sync.noCandidate') }}</p>
        <label v-if="store.decisions.some(d => d.decision === 'keep-current')" class="sync-confirm"><input v-model="store.keepConfirmed" type="checkbox" data-testid="sync-keep-confirm" />{{ t('sync.keepConfirm') }}</label><p v-if="store.blockReason && !store.candidateSuperseded" data-testid="sync-apply-reason">{{ reason(store.blockReason) }}</p><button data-testid="sync-apply" :disabled="!!store.blockReason || !can('sync.apply')" @click="action(() => store.apply())">{{ t('sync.apply') }}</button>
      </section>
      <section v-if="store.intentId"><h3>{{ t('sync.receipt') }}: {{ store.receipt ? t('sync.committed') : t('sync.pending') }}</h3><dl><dt>{{ t('sync.receiptSource') }}</dt><dd>{{ store.intentSourceId }}</dd><dt>{{ t('sync.intent') }}</dt><dd>{{ store.intentId }}</dd><template v-if="store.receipt"><dt>{{ t('sync.actor') }}</dt><dd>{{ store.receipt.actor.name }}</dd><dt>{{ t('sync.completed') }}</dt><dd>{{ utcTime(store.receipt.completedAtMs) }}</dd><dt>{{ t('sync.definition') }}</dt><dd>{{ shortIdentity(store.receipt.afterStamp.definitionRevision) }}</dd></template></dl><button v-if="!store.receipt" @click="store.reconcile()">{{ t('sync.reconcile') }}</button><p v-if="store.refreshError" role="alert">{{ t('sync.refreshFailed') }} {{ reason(store.refreshError) }}</p></section>
      <div id="sync-history" tabindex="-1"><SyncHistory :entries="store.history" :search="search" :disabled="store.applying || !can('sync.apply')" @rollback="entry => action(() => store.rollback(entry))" /></div>
      <section><h3>{{ t('sync.schedule') }}</h3><p>{{ t('sync.scheduleOnlyChecks') }}</p><p v-if="store.scope?.kind === 'local'">{{ t('sync.scheduleLocal') }}</p><template v-else-if="store.schedule"><p>{{ store.schedule.pausedReasonCode ? t('sync.paused') : t(store.schedule.enabled ? 'sync.enabled' : 'sync.disabled') }}</p><p v-if="store.schedule.pausedReasonCode">{{ reason(store.schedule.pausedReasonCode) }}</p><dl><dt>{{ t('sync.subject') }}</dt><dd>{{ store.schedule.subjectUserId ?? t('sync.notCollected') }}</dd><dt>{{ t('sync.generation') }}</dt><dd>{{ store.schedule.generation }}</dd></dl><p>{{ t('sync.nextNotCalculated') }}</p>
        <label>{{ t('sync.cron') }}<input v-model="rule.expression" /></label><label>{{ t('sync.timeZone') }}<input v-model="rule.timeZone" /></label><label>{{ t('sync.overlap') }}<select v-model="rule.dstOverlap"><option value="first">{{ t('sync.first') }}</option><option value="both">{{ t('sync.both') }}</option></select></label><button :disabled="store.scheduleBusy || !can('sync.manage') || !can('sync.check')" @click="store.saveSchedule(true, { ...rule })">{{ t('sync.authorize') }}</button><button :disabled="store.scheduleBusy || !can('sync.manage') || !can('sync.check')" @click="store.saveSchedule(false, { ...rule })">{{ t('sync.disableSchedule') }}</button><button @click="action(() => store.previewSchedule({ ...rule }))">{{ t('sync.previewSchedule') }}</button><p v-if="store.scheduleError" role="alert">{{ reason(store.scheduleError) }}</p><ol v-if="store.preview"><li v-for="candidate in store.preview.candidates" :key="candidate.plannedAtUtc"><time :title="candidate.plannedAtUtc">{{ utcTime(candidate.plannedAtUtc) }}</time> · {{ candidate.localTime }} {{ candidate.offset }}</li></ol><p v-for="notice in store.preview?.notices ?? []" :key="notice">{{ reason(notice) }}</p>
        <section v-if="store.schedule.lastOccurrence"><h4>{{ t('sync.lastOccurrence') }}</h4><p>{{ t('sync.' + store.schedule.lastOccurrence.associationState) }} · {{ t('sync.' + store.schedule.lastOccurrence.state) }}</p><p><time :title="store.schedule.lastOccurrence.plannedAtUtc">{{ utcTime(store.schedule.lastOccurrence.plannedAtUtc) }}</time></p><dl><dt>{{ t('sync.dueCount') }}</dt><dd>{{ store.schedule.lastOccurrence.coalescedDueCount ?? t('sync.notCollected') }}</dd><dt>{{ t('sync.requestedSubject') }}</dt><dd>{{ store.schedule.lastOccurrence.requestedSubjectUserId ?? t('sync.notCollected') }}</dd><dt>{{ t('sync.executedSubject') }}</dt><dd>{{ store.schedule.lastOccurrence.executedSubjectUserId ?? t('sync.notCollected') }}</dd><dt>{{ t('sync.window') }}</dt><dd>{{ utcTime(store.schedule.lastOccurrence.evaluatedAfterUtc) ?? t('sync.notCollected') }} → {{ utcTime(store.schedule.lastOccurrence.evaluatedThroughUtc) ?? t('sync.notCollected') }}</dd></dl><p v-if="store.schedule.lastOccurrence.missedBeforeWindow">{{ t('sync.missedWindow') }}</p><button v-if="store.schedule.lastOccurrence.checkId" @click="store.readCheck(store.schedule!.lastOccurrence!.checkId!)">{{ t('sync.checkState') }}</button></section>
      </template></section>
      <section id="sync-settings" tabindex="-1"><h3>{{ t('sync.settings') }}</h3><p>{{ t('sync.nextCheck') }}</p><p>{{ t('sync.diskThreshold') }}</p><p>{{ t('sync.projectBytes') }}</p><p v-if="store.policy?.status === 'invalid'" role="alert">{{ t('sync.invalidPolicy') }}</p>
        <template v-if="store.settings"><p v-if="store.settings.git === 'missing'">{{ t('sync.gitMissing') }}</p><p v-if="store.settings.ssh === 'missing'">{{ t('sync.sshMissing') }}</p><button @click="action(() => store.configureTool('git'))">{{ t('sync.selectGit') }}</button><button @click="action(() => store.configureTool('ssh'))">{{ t('sync.selectSsh') }}</button><label>{{ t('sync.maxRedirects') }} (0–20)<input v-model.number="redirects" type="number" min="0" max="20" /></label><p>{{ t('sync.revision') }}: {{ store.settings.revision ?? '0' }}</p></template>
        <p v-if="store.policy">{{ t('sync.revision') }}: {{ store.policy.saved.revision }} · {{ t('sync.workspace') }}: {{ store.policy.workspaceRevision }} · RPC {{ store.policy.deploymentLimits.maxWireBytes.toLocaleString() }} {{ t('sync.bytes') }}</p>
        <div class="sync-table-scroll"><table v-if="store.settings || store.policy"><thead><tr><th>{{ t('sync.settings') }}</th><th>{{ t('sync.default') }}</th><th>{{ t('sync.saved') }}</th><th>{{ t('sync.effective') }}</th><th>{{ t('sync.provenance') }}</th><th>{{ t('sync.constraint') }}</th></tr></thead><tbody><tr v-for="field in policyFields" :key="field.key"><th>{{ t('sync.policyFields.' + field.key) }}</th><td>{{ fieldValue(defaultSyncPolicyValues[field.key], field.unit) }}</td><td><label v-if="store.settings"><span class="sync-sr-only">{{ t('sync.policyFields.' + field.key) }} · {{ t('sync.' + field.unit) }}</span><input v-model.number="policyDraft[field.key]" type="number" :min="field.min" :max="field.max" step="1" /></label><span v-else>{{ fieldValue(store.policy?.saved[field.key], field.unit) }}</span></td><td>{{ store.settings ? fieldValue(store.settings.policy[field.key], field.unit) : store.policy?.effective ? fieldValue(store.policy.effective.policy[field.key], field.unit) : t('sync.unavailable') }}</td><td>{{ store.settings ? t(store.settings.revision && store.settings.revision !== '0' ? 'sync.local' : 'sync.default') : store.policy?.effective ? t('sync.' + store.policy.effective.sources[field.key]) : t('sync.unavailable') }}</td><td>{{ fieldValue(field.min, field.unit) }} – {{ fieldValue(field.max, field.unit) }}<span v-if="store.policy?.deploymentCeilings[field.key] !== undefined"> · {{ t('sync.deployment') }}: {{ fieldValue(store.policy?.deploymentCeilings[field.key], field.unit) }}</span></td></tr></tbody></table></div><button v-if="store.settings" :disabled="!!readOnly" @click="action(() => store.saveSettings({ maxRedirects: redirects, policy: { ...policyDraft } }))">{{ t('sync.saveSettings') }}</button>
      </section>
    </div>
  </section>
</template>
